  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Calculates the final trip price after applying a 20% discount if the customer has a DISCOUNTS reward and the booking is made at least 24 hours before departure.
   * Algorithm:
   *   1. If customer is null or customer.membershipPackage is null, return this.price.
   *   2. If customer.membershipPackage.hasAward(DISCOUNTS) is false, return this.price.
   *   3. Parse bookingTime and this.departureTime as "yyyy-MM-dd HH:mm" datetime strings.
   *   4. If (this.departureTime - bookingTime) < 24 hours, return this.price.
   *   5. Calculate discountedPrice = this.price * 0.8.
   *   6. Return discountedPrice rounded to one decimal place.
   * Related Features: price, departureTime, customer.membershipPackage
   * Related Classes: Customer, MembershipPackage, Award
   * Input: customer : Customer - the customer making the booking; bookingTime : String - the booking datetime in "yyyy-MM-dd HH:mm" format.
   * Output: double - the final price with one decimal place (original price if no discount applies).
   * Pre-condition: None
   * Post-condition: Returns the discounted or original price based on eligibility.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    // Step 1: If customer is null or customer.membershipPackage is null, return this.price.
    if (customer == null || customer.getMembershipPackage() == null) {
      return this.price;
    }

    // Step 2: If customer.membershipPackage.hasAward(DISCOUNTS) is false, return this.price.
    if (!customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return this.price;
    }

    // Step 3: Parse bookingTime and this.departureTime as "yyyy-MM-dd HH:mm" datetime strings.
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm");
    try {
      Date bookingDateTime = sdf.parse(bookingTime);
      Date departureDateTime = sdf.parse(this.departureTime);

      // Step 4: If (this.departureTime - bookingTime) < 24 hours, return this.price.
      long diffInMillis = departureDateTime.getTime() - bookingDateTime.getTime();
      long twentyFourHoursInMillis = 24 * 60 * 60 * 1000;
      if (diffInMillis < twentyFourHoursInMillis) {
        return this.price;
      }

      // Step 5: Calculate discountedPrice = this.price * 0.8.
      double discountedPrice = this.price * 0.8;

      // Step 6: Return discountedPrice rounded to one decimal place.
      return Math.round(discountedPrice * 10.0) / 10.0;

    } catch (ParseException e) {
      // If parsing fails, return the original price
      return this.price;
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Computes the reward points earned by a customer for a given month, based on POINTS reward eligibility.
   * Algorithm:
   *   1. If customer is null, customer.membershipPackage is null, or currentMonth is null, return 0.
   *   2. If customer.membershipPackage.hasAward(POINTS) is false, return 0.
   *   3. Initialize totalPoints = 0.
   *   4. For each booking in customer.bookings:
   *      - If booking.bookingDate falls within the month specified by currentMonth (yyyy-MM format),
   *        add (booking.numberOfSeats * 5) to totalPoints.
   *   5. Return totalPoints.
   * Related Features: customer.bookings, customer.membershipPackage, numberOfSeats, bookingDate
   * Related Classes: Customer, MembershipPackage, Award, Booking
   * Input: currentMonth : String - the month in "yyyy-MM" format.
   * Output: int - total reward points earned (0 if ineligible).
   * Pre-condition: None
   * Post-condition: Returns the computed points or 0 for invalid inputs.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    // Step 1: If customer is null, customer.membershipPackage is null, or currentMonth is null, return 0.
    if (customer == null || customer.getMembershipPackage() == null || currentMonth == null) {
      return 0;
    }

    // Step 2: If customer.membershipPackage.hasAward(POINTS) is false, return 0.
    if (!customer.getMembershipPackage().hasAward(Award.POINTS)) {
      return 0;
    }

    // Step 3: Initialize totalPoints = 0.
    int totalPoints = 0;

    // Step 4: For each booking in customer.bookings:
    for (Booking booking : customer.getBookings()) {
      // If booking.bookingDate falls within the month specified by currentMonth (yyyy-MM format)
      if (booking.getBookingDate() != null) {
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM");
        String bookingMonth = sdf.format(booking.getBookingDate());
        if (bookingMonth.equals(currentMonth)) {
          // add (booking.numberOfSeats * 5) to totalPoints.
          totalPoints += booking.getNumberOfSeats() * 5;
        }
      }
    }

    // Step 5: Return totalPoints.
    return totalPoints;
  }

